    if (trail.status === "merged") return null
    if (!trail.reviewers?.length) return null
    const approved = trail.reviewers.filter((r) => r.status === "approved").length
    const changesRequested = trail.reviewers.some((r) => r.status === "changes_requested")
    if (changesRequested)
      return {
        label: "Changes requested",
        color: "bg-orange-100 text-orange-700 dark:bg-orange-900/30 dark:text-orange-400",
      }
    if (approved === trail.reviewers.length)
      return {
        label: "Approved",
        color: "bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400",
      }
    return {
      label: `${approved}/${trail.reviewers.length} approved`,
