// Check GitHub org membership using the GitHub App's installation token.
// This distinguishes real org members from outside collaborators.

import type { Env } from "../env"
import type { Db } from "./db/db-types"
import { getInstallationToken, type AppTokenConfig } from "./token"

const ENTIREHQ_ORG = "entirehq"

// Timeout for the GitHub membership API call (2 seconds)
const MEMBERSHIP_CHECK_TIMEOUT_MS = 2000

export interface MembershipCheckResult {
  isMember: boolean
  role: string | null // "admin" or "member", null if not a member
  fromCache: boolean // true if result came from DB fallback
}

/**
 * Check if a GitHub user is a member of the entirehq organization.
 * Uses the GitHub App's installation token (no user OAuth scope needed).
 *
 * On success: updates org_memberships with role and membership_checked_at.
 * On failure/timeout: falls back to last-known membership from DB.
 */
export async function checkEntireOrgMembership(
  db: Db,
  env: Env,
  userId: string,
  githubLogin: string,
): Promise<MembershipCheckResult> {
  try {
    const result = await checkMembershipViaGitHubApi(db, env, githubLogin)

    if (result.isMember) {
      await db.orgMemberships.upsertWithRole(
        userId,
        result.orgAccountId,
        ENTIREHQ_ORG,
        result.role!,
      )
    } else {
      // Remove stale membership for this org
      await db.orgMemberships.deleteByOrgLogin(userId, ENTIREHQ_ORG)
    }

    return { isMember: result.isMember, role: result.role, fromCache: false }
  } catch (err) {
    console.warn(`GitHub org membership check failed for ${githubLogin}, falling back to DB:`, err)
    return fallbackToDb(db, userId)
  }
}

async function checkMembershipViaGitHubApi(
  db: Db,
  env: Env,
  githubLogin: string,
): Promise<{ isMember: boolean; role: string | null; orgAccountId: number }> {
  // Get the entirehq installation's GitHub ID and account ID
  const installationGithubId = await db.installations.getGithubIdByOwner(ENTIREHQ_ORG)
  if (!installationGithubId) {
    throw new Error("entirehq installation not found in database")
  }

  const orgAccountId = await db.installations.getAccountIdByOwner(ENTIREHQ_ORG)
  if (!orgAccountId) {
    throw new Error("entirehq account ID not found in database")
  }

  const appConfig: AppTokenConfig = {
    appId: env.GITHUB_CLIENT_ID,
    privateKey: env.GITHUB_APP_PRIVATE_KEY,
  }

  // Get the App's installation token (cached in KV for 50 min)
  const token = await getInstallationToken(installationGithubId, appConfig, env.ENTIRE_CACHE)

  // Check membership with a timeout
  const controller = new AbortController()
  const timeoutId = setTimeout(() => controller.abort(), MEMBERSHIP_CHECK_TIMEOUT_MS)

  try {
    const response = await fetch(
      `https://api.github.com/orgs/${ENTIREHQ_ORG}/members/${githubLogin}`,
      {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/vnd.github+json",
          "User-Agent": "entire-api",
          "X-GitHub-Api-Version": "2022-11-28",
        },
        signal: controller.signal,
        redirect: "manual",
      },
    )

    if (response.status === 204) {
      // User is a member — fetch the specific role
      const role = await fetchMemberRole(token, githubLogin, controller.signal)
      return { isMember: true, role, orgAccountId }
    }

    if (response.status === 404 || response.status === 302) {
      // 404 = definitively not a member, 302 = not visible (treat as not a member)
      return { isMember: false, role: null, orgAccountId }
    }

    // Any other status (5xx, 403 rate limit, 401 auth error) is not a definitive
    // answer — throw so the caller falls back to cached DB membership instead of
    // incorrectly treating a transient error as "not a member".
    throw new Error(`GitHub org membership check returned unexpected status ${response.status}`)
  } finally {
    clearTimeout(timeoutId)
  }
}

/**
 * Fetch the specific role (admin/member) for an org member.
 * Falls back to "member" if the role check fails.
 */
async function fetchMemberRole(
  token: string,
  githubLogin: string,
  signal: AbortSignal,
): Promise<string> {
  try {
    const response = await fetch(
      `https://api.github.com/orgs/${ENTIREHQ_ORG}/memberships/${githubLogin}`,
      {
        headers: {
          Authorization: `Bearer ${token}`,
          Accept: "application/vnd.github+json",
          "User-Agent": "entire-api",
          "X-GitHub-Api-Version": "2022-11-28",
        },
        signal,
      },
    )

    if (response.ok) {
      const data = await response.json<{ role: string }>()
      return data.role // "admin" or "member"
    }
  } catch {
    // Fall through to default
  }
  return "member"
}

/**
 * Fall back to the last-known membership from the database.
 */
async function fallbackToDb(db: Db, userId: string): Promise<MembershipCheckResult> {
  const membership = await db.orgMemberships.findByUserAndOrgLogin(userId, ENTIREHQ_ORG)

  if (membership && membership.role) {
    return { isMember: true, role: membership.role, fromCache: true }
  }

  return { isMember: false, role: null, fromCache: true }
}

