/**
 * Generate a unique trail ID (12 hex characters)
 */
export function generateTrailId(): string {
  const array = new Uint8Array(6)
  crypto.getRandomValues(array)
  return Array.from(array, (b) => b.toString(16).padStart(2, "0")).join("")
}

