/**
 * Belt-and-suspenders wrapper for request-path callers of the new commit
 * services. The services are DB-only today, but any future addition (a
 * Connect call, a drift-signal regression, an unexpected DB error pattern)
 * shouldn't surface as a user-facing 5xx when the legacy path can still
 * serve. Catches anything thrown by `primary` and degrades to `legacy`.
 *
 * The fallback skips whatever side effect the primary may have triggered
 * (e.g. drift-signal enqueue). That's tolerable because the audit job
 * catches drift independently.
 *
 * Use sparingly: only at request-path entry points where graceful
 * degradation is correct. Job/queue paths should let errors propagate so
 * the queue's retry policy can do its job.
 */
export async function withGitSourceFallback<T>(
  context: string,
  primary: () => Promise<T>,
  legacy: () => Promise<T>,
): Promise<T> {
  try {
    return await primary()
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    console.warn(`[git-source] ${context} fell back to legacy: ${message}`)
    trace.getActiveSpan()?.addEvent("git_source.route_fallback", {
      "git_source.context": context,
      "git_source.error": message,
    })
    return legacy()
  }
}
import type { Env } from "../env"
import type { Db } from "./db/db-types"
import type { Repo } from "./db/repos"
import { getInstallationToken } from "./token"

/**
 * Thrown when the repo has a linked installation but the token exchange with
 * GitHub failed (transient network/GitHub/JWT error, or the installation was
 * removed on GitHub's side). Distinct from "no installation configured", which
 * is signalled by a plain `undefined` return. Only surfaced when the caller
 * opts in via `rethrowExchangeError`.
 */
export class InstallationTokenExchangeError extends Error {
  constructor(
    public readonly repoFullName: string,
    cause: unknown,
  ) {
    super(`Installation token exchange failed for ${repoFullName}`, { cause })
    this.name = "InstallationTokenExchangeError"
  }
}

interface GetInstallationTokenOptions {
  /**
   * When true, a failed token exchange throws InstallationTokenExchangeError
   * instead of being swallowed into `undefined`. Lets callers tell a transient
   * exchange failure (retryable, should surface as 5xx) apart from a repo that
   * genuinely has no installation (still returns `undefined`). Defaults to the
   * legacy swallow-everything behavior the fallback callers rely on.
   */
  rethrowExchangeError?: boolean
}

/**
 * Fetch a GitHub App installation token for the repo's associated installation.
 * Returns undefined when the repo has no installation or the installation row
 * has no github_id.
 *
 * By default the token exchange never throws — a failed exchange also returns
 * undefined, so callers that fall back to the viewer's OAuth token degrade
 * gracefully. Pass `rethrowExchangeError: true` to instead surface the failure
 * as InstallationTokenExchangeError, so a transient exchange error doesn't
 * masquerade as "App not installed".
 */
export async function getInstallationTokenForRepo(
  db: Db,
  env: Env,
  repo: Repo | null,
  options?: GetInstallationTokenOptions,
): Promise<string | undefined> {
  if (!repo?.installation_id) return undefined

  const githubInstallationId = await db.installations.getGithubId(repo.installation_id)
  if (!githubInstallationId) return undefined

  try {
    return await getInstallationToken(
      githubInstallationId,
      { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
      env.ENTIRE_CACHE,
    )
  } catch (err) {
    if (options?.rethrowExchangeError) {
      throw new InstallationTokenExchangeError(repo.full_name, err)
    }
    return undefined
  }
}
