// Combines trail lookup with GitHub token resolution
async function resolveTrailWithGitHubContext(
  c: TrailContext,
): Promise<(ResolvedTrailContext & ResolvedGitHubContext) | Response> {
  const base = await resolveTrailContext(c)
  if (base instanceof Response) return base

  const user = await base.db.users.findById(base.userId)
  if (!user) {
    return c.json({ error: "User not found" }, 404)
  }

  let token: string | undefined
  if (user.github_token_enc) {
    const result = await getValidGitHubTokenFromContext(c, base.db, user)
    token = result.token
  }

  if (!token) {
    return c.json({ error: "GitHub token required" }, 401)
  }

  return { ...base, user, githubToken: token }
}

// Trail lookup with an App installation token, for reads that don't act as the
// user (diff, mergeability). The installation token can always read a trail
// repo and is never subject to user-token expiry, so these reads don't break
// when the viewer's OAuth token is stale — unlike resolveTrailWithGitHubContext,
// which hands back a (possibly dead) user token that GitHub then rejects.
//
// We deliberately don't fall back to the viewer's token here. A genuinely
// missing installation degrades far more than these two reads, and the product
// already surfaces it (has_app_installation + the App install flow), so a 409
// pointing at that remediation is the honest response. The one failure mode we
// must not mislabel as "not installed" is a transient token-exchange error
// (network/GitHub/JWT) on a repo that *is* installed — rethrowExchangeError
// distinguishes it so we can return a retryable 503 instead of a 409.
async function resolveTrailWithInstallationToken(
  c: TrailContext,
): Promise<(ResolvedTrailContext & { githubToken: string }) | Response> {
  const base = await resolveTrailContext(c)
  if (base instanceof Response) return base

  let token: string | undefined
  try {
    token = await getInstallationTokenForRepo(base.db, c.env, base.repo, {
      rethrowExchangeError: true,
    })
  } catch (err) {
    console.error(`Installation token exchange failed for ${base.repoFullName}:`, err)
    return c.json({ error: "GitHub App token temporarily unavailable" }, 503)
  }
  if (!token) {
    return c.json({ error: "GitHub App installation required" }, 409)
  }

  return { ...base, githubToken: token }
}

