async function deleteRecentRepo(db: DbExecutor, userId: string, repoId: string): Promise<boolean> {
  const result = await db
    .deleteFrom("user_repo_preferences")
    .where("user_id", "=", userId)
    .where("type", "=", "recent")
    .where("repo_id", "=", repoId)
    .executeTakeFirst()

  return Number(result.numDeletedRows ?? 0) > 0
}

async function trimRecentRepos(db: DbExecutor, userId: string): Promise<void> {
  const rows = await db
    .selectFrom("user_repo_preferences")
    .select("id")
    .where("user_id", "=", userId)
    .where("type", "=", "recent")
    .orderBy("recent_at", "desc")
    .orderBy("created_at", "asc")
    .orderBy("id", "asc")
    .execute()

  const overflowRows = rows.slice(MAX_RECENT)

  if (overflowRows.length === 0) {
    return
  }

  await db
    .deleteFrom("user_repo_preferences")
    .where(
      "id",
      "in",
      overflowRows.map((row) => row.id),
    )
    .execute()
}

